import re
import subprocess
from flask import Flask, request, jsonify

app = Flask(__name__)


def error_response(code, message, status=400):
    return jsonify({"code": code, "message": message}), status


def parse_ps_output(output):
    """Parse ps output into list of (pid, full_command_string) tuples."""
    lines = output.splitlines()
    results = []
    for line in lines:
        line = line.rstrip()
        if not line.strip():
            continue
        # ps aux format: USER PID %CPU %MEM VSZ RSS TTY STAT START TIME COMMAND
        # ps -ef format: UID PID PPID C STIME TTY TIME CMD
        # We try to detect PID position based on header, fallback to second field.
        parts = line.split(None, 10)
        if len(parts) < 2:
            continue
        pid_str = parts[1]
        if not pid_str.isdigit():
            continue
        pid = int(pid_str)
        # The command string is the remainder after the fixed columns.
        # For aux: 10 fixed fields then command -> parts[10]
        # For -ef: 7 fixed fields then command
        # We'll reconstruct by finding the command portion.
        # Simplest robust approach: use the last split with maxsplit matching.
        results.append((pid, line, parts))
    return results


def run_ps(filter_flags):
    """Run ps with given flags and return raw output."""
    # Build command. filter_flags is user-provided; we must be careful.
    # We split on whitespace and pass as args (no shell).
    args = ["ps"]
    if filter_flags:
        # Basic sanitization: only allow safe characters
        if not re.fullmatch(r"[A-Za-z0-9_\-\.\s,=]*", filter_flags):
            raise ValueError("Invalid filter_flags")
        args.extend(filter_flags.split())
    else:
        args.append("aux")
    proc = subprocess.run(args, capture_output=True, text=True, timeout=30)
    if proc.returncode != 0:
        raise RuntimeError(proc.stderr.strip() or "ps command failed")
    return proc.stdout


def extract_command(line, filter_flags):
    """Extract the command string from a ps output line."""
    # Determine number of fixed columns based on flags.
    flags = (filter_flags or "aux").lower()
    if "aux" in flags or "a" in flags and "u" in flags and "x" in flags:
        # aux: USER PID %CPU %MEM VSZ RSS TTY STAT START TIME COMMAND (10 fields)
        parts = line.split(None, 10)
        if len(parts) >= 11:
            return parts[10]
        return line
    if "-ef" in flags or "ef" in flags:
        # -ef: UID PID PPID C STIME TTY TIME CMD (7 fields)
        parts = line.split(None, 7)
        if len(parts) >= 8:
            return parts[7]
        return line
    # fallback: everything after PID
    parts = line.split(None, 2)
    if len(parts) >= 3:
        return parts[2]
    return line


@app.route("/monitor/commands", methods=["POST"])
def monitor_commands():
    data = request.get_json(silent=True)
    if data is None or not isinstance(data, dict):
        return error_response(400, "Request body must be a JSON object")

    command_regex = data.get("command_regex")
    if command_regex is None or not isinstance(command_regex, str):
        return error_response(400, "command_regex is required and must be a string")

    filter_flags = data.get("filter_flags", "")
    if filter_flags is None:
        filter_flags = ""
    if not isinstance(filter_flags, str):
        return error_response(400, "filter_flags must be a string")

    try:
        regex = re.compile(command_regex)
    except re.error as e:
        return error_response(400, f"Invalid regular expression: {e}")

    try:
        output = run_ps(filter_flags)
    except ValueError as e:
        return error_response(400, str(e))
    except subprocess.TimeoutExpired:
        return error_response(500, "ps command timed out", 500)
    except RuntimeError as e:
        return error_response(500, str(e), 500)

    results = []
    lines = output.splitlines()
    # Skip header line if present
    start_idx = 0
    if lines:
        header = lines[0].split()
        if header and header[0].upper() in ("USER", "UID"):
            start_idx = 1

    for line in lines[start_idx:]:
        if not line.strip():
            continue
        parts = line.split(None, 2)
        if len(parts) < 2 or not parts[1].isdigit():
            continue
        pid = int(parts[1])
        cmd = extract_command(line, filter_flags)
        if regex.search(cmd):
            results.append({"processId": pid, "processString": cmd})

    return jsonify(results), 200


@app.errorhandler(404)
def not_found(e):
    return error_response(404, "Not found", 404)


@app.errorhandler(405)
def method_not_allowed(e):
    return error_response(405, "Method not allowed", 405)


@app.errorhandler(500)
def internal_error(e):
    return error_response(500, "Internal server error", 500)


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
